#!/usr/bin/env node
// scripts/lib/dmarc-report-parser.js — decode and parse DMARC aggregate
// reports (RFC 7489) into a normalized shape.
//
// WHY ZERO DEPENDENCIES: the reports arrive as gzip or zip XML. Node ships
// zlib, and DMARC aggregate XML is machine-generated by a handful of reporters
// (Google, Microsoft, Zoho, Yahoo) against a fixed schema — no namespaces, no
// attributes, no CDATA, no mixed content. A general XML parser would be a new
// npm dependency in the install path of 60+ workflows to read a grammar this
// small. The tradeoff is that the parser must be validated against the real
// corpus rather than two fixtures, which is what
// scripts/tests/dmarc-report-parser.test.mjs does (real Google + Microsoft +
// Zoho reports, plus malformed input).
//
// Pure functions only — no fs, no network, no process. The I/O lives in
// scripts/ingest-dmarc-reports.js.
//
// Tested by scripts/tests/dmarc-report-parser.test.mjs (CLAUDE.md rule 15 —
// the test require()s these functions, it does not restate them).

'use strict';

const zlib = require('zlib');

const XML_ENTITIES = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'" };

function decodeEntities(s) {
  return s.replace(/&(#x?[0-9a-fA-F]+|[a-zA-Z]+);/g, (m, ent) => {
    if (ent[0] === '#') {
      const code = ent[1] === 'x' || ent[1] === 'X'
        ? parseInt(ent.slice(2), 16)
        : parseInt(ent.slice(1), 10);
      return Number.isFinite(code) ? String.fromCodePoint(code) : m;
    }
    return Object.prototype.hasOwnProperty.call(XML_ENTITIES, ent) ? XML_ENTITIES[ent] : m;
  });
}

/**
 * Minimal XML -> plain-object parser for the DMARC aggregate grammar.
 *
 * Repeated sibling tags become arrays; an element with no element children
 * collapses to its trimmed text. This is deliberately NOT a general XML
 * parser — it understands no namespaces and no attributes, so it must only
 * ever be pointed at DMARC reports.
 */
function parseXml(xml) {
  if (typeof xml !== 'string') throw new TypeError('parseXml expects a string');
  const body = xml
    .replace(/<\?[\s\S]*?\?>/g, '')
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<!DOCTYPE[^>]*>/gi, '');

  const tagRe = /<\s*(\/)?\s*([A-Za-z_][\w.:-]*)([^>]*?)(\/)?\s*>/g;
  const root = {};
  // Each frame owns the object its children are written into.
  const stack = [{ name: '#root', obj: root, parent: null }];
  let cursor = 0;
  let match;

  while ((match = tagRe.exec(body)) !== null) {
    const full = match[0];
    const closing = match[1];
    const name = match[2];
    const selfClosing = match[4];
    const text = body.slice(cursor, match.index);
    cursor = match.index + full.length;

    if (closing) {
      const frame = stack.pop();
      if (!frame || frame.parent === null) throw new Error(`unbalanced closing tag </${name}>`);
      if (frame.name !== name) throw new Error(`mismatched tag: expected </${frame.name}>, got </${name}>`);
      // Leaf: no element children were added, so collapse to text.
      if (Object.keys(frame.obj).length === 0) {
        replaceLast(frame.parent, frame.name, decodeEntities(text).trim());
      }
      continue;
    }

    const parent = stack[stack.length - 1].obj;
    if (selfClosing) { addChild(parent, name, ''); continue; }
    const obj = {};
    addChild(parent, name, obj);
    stack.push({ name, obj, parent });
  }

  if (stack.length !== 1) throw new Error(`unclosed tag <${stack[stack.length - 1].name}>`);
  return root;
}

function addChild(parent, key, value) {
  if (!Object.prototype.hasOwnProperty.call(parent, key)) { parent[key] = value; return; }
  if (Array.isArray(parent[key])) { parent[key].push(value); return; }
  parent[key] = [parent[key], value];
}

// Replace the placeholder object most recently added for `key` with the
// leaf's text, preserving array position for repeated tags.
function replaceLast(parent, key, value) {
  if (Array.isArray(parent[key])) parent[key][parent[key].length - 1] = value;
  else parent[key] = value;
}

/** Always return an array, whether the tag appeared 0, 1 or N times. */
function asArray(v) {
  if (v === undefined || v === null) return [];
  return Array.isArray(v) ? v : [v];
}

function str(v) {
  if (typeof v === 'string') return v.trim();
  return '';
}

function epochToIso(v) {
  const n = Number(str(v));
  if (!Number.isFinite(n) || n <= 0) return null;
  return new Date(n * 1000).toISOString();
}

/**
 * Decompress a report attachment. Reporters ship gzip (Microsoft, Zoho), zip
 * (Google) or bare XML; dispatch on magic bytes, not on the filename, because
 * the filename is reporter-controlled and inconsistent.
 */
function unpackReport(buffer) {
  if (!Buffer.isBuffer(buffer)) throw new TypeError('unpackReport expects a Buffer');
  if (buffer.length < 4) throw new Error('report payload too short to be a DMARC report');
  if (buffer[0] === 0x1f && buffer[1] === 0x8b) return zlib.gunzipSync(buffer).toString('utf8');
  if (buffer[0] === 0x50 && buffer[1] === 0x4b) return unzipSingleEntry(buffer).toString('utf8');
  return buffer.toString('utf8');
}

/**
 * Extract the first real file from a ZIP archive.
 *
 * Reads the central directory rather than scanning for local file headers: a
 * local header may carry zeroed sizes with the real values in a trailing data
 * descriptor, so local-header sizes cannot be trusted. Supports the two
 * methods DMARC reporters actually emit — stored (0) and deflate (8).
 */
function unzipSingleEntry(buf) {
  const EOCD_SIG = 0x06054b50;
  let eocd = -1;
  const minStart = Math.max(0, buf.length - 22 - 0xffff);
  for (let i = buf.length - 22; i >= minStart; i--) {
    if (buf.readUInt32LE(i) === EOCD_SIG) { eocd = i; break; }
  }
  if (eocd < 0) throw new Error('not a zip archive: end-of-central-directory record not found');

  const entryCount = buf.readUInt16LE(eocd + 10);
  let offset = buf.readUInt32LE(eocd + 16);
  if (entryCount < 1) throw new Error('zip archive contains no entries');

  for (let i = 0; i < entryCount; i++) {
    if (buf.readUInt32LE(offset) !== 0x02014b50) throw new Error('corrupt zip central directory');
    const method = buf.readUInt16LE(offset + 10);
    const compressedSize = buf.readUInt32LE(offset + 20);
    const nameLen = buf.readUInt16LE(offset + 28);
    const extraLen = buf.readUInt16LE(offset + 30);
    const commentLen = buf.readUInt16LE(offset + 32);
    const localOffset = buf.readUInt32LE(offset + 42);
    const name = buf.slice(offset + 46, offset + 46 + nameLen).toString('utf8');
    offset += 46 + nameLen + extraLen + commentLen;

    if (name.endsWith('/')) continue; // directory entry

    if (buf.readUInt32LE(localOffset) !== 0x04034b50) throw new Error('corrupt zip local header');
    const localNameLen = buf.readUInt16LE(localOffset + 26);
    const localExtraLen = buf.readUInt16LE(localOffset + 28);
    const dataStart = localOffset + 30 + localNameLen + localExtraLen;
    const data = buf.slice(dataStart, dataStart + compressedSize);
    if (method === 0) return data;
    if (method === 8) return zlib.inflateRawSync(data);
    throw new Error(`unsupported zip compression method ${method}`);
  }
  throw new Error('zip archive contains no readable file entry');
}

/**
 * Parse DMARC aggregate XML into a normalized report.
 *
 * Every optional field is defensive: reporters omit elements freely
 * (Microsoft omits <selector>, Zoho omits <envelope_to>, Google adds <np>),
 * and a missing optional element must never throw — a report that throws is a
 * report nobody reads.
 */
function parseAggregateReport(xml) {
  const doc = parseXml(xml);
  const fb = doc.feedback;
  if (!fb || typeof fb !== 'object') throw new Error('not a DMARC aggregate report: missing <feedback> root');

  const meta = (typeof fb.report_metadata === 'object' && fb.report_metadata) || {};
  const range = (typeof meta.date_range === 'object' && meta.date_range) || {};
  const pol = (typeof fb.policy_published === 'object' && fb.policy_published) || {};

  const records = asArray(fb.record).filter((r) => r && typeof r === 'object').map(normalizeRecord);
  const pct = str(pol.pct);

  return {
    orgName: str(meta.org_name),
    orgEmail: str(meta.email),
    reportId: str(meta.report_id),
    dateBegin: epochToIso(range.begin),
    dateEnd: epochToIso(range.end),
    policy: {
      domain: str(pol.domain).toLowerCase(),
      adkim: str(pol.adkim) || 'r',
      aspf: str(pol.aspf) || 'r',
      p: str(pol.p),
      sp: str(pol.sp),
      np: str(pol.np),
      pct: pct === '' ? 100 : Number(pct),
    },
    records,
    messageCount: records.reduce((n, r) => n + r.count, 0),
  };
}

function normalizeRecord(rec) {
  const row = (typeof rec.row === 'object' && rec.row) || {};
  const evaluated = (typeof row.policy_evaluated === 'object' && row.policy_evaluated) || {};
  const ids = (typeof rec.identifiers === 'object' && rec.identifiers) || {};
  const auth = (typeof rec.auth_results === 'object' && rec.auth_results) || {};

  const count = Number(str(row.count));
  return {
    sourceIp: str(row.source_ip),
    count: Number.isFinite(count) && count > 0 ? count : 0,
    disposition: str(evaluated.disposition) || 'none',
    evaluatedDkim: str(evaluated.dkim),
    evaluatedSpf: str(evaluated.spf),
    // Why a message that failed DMARC was delivered anyway — usually
    // 'local_policy' (receiver allowlist) or 'forwarded'.
    overrides: asArray(evaluated.reason)
      .map((r) => (r && typeof r === 'object' ? str(r.type) : str(r)))
      .filter(Boolean),
    headerFrom: str(ids.header_from).toLowerCase(),
    envelopeFrom: str(ids.envelope_from).toLowerCase(),
    envelopeTo: str(ids.envelope_to).toLowerCase(),
    dkim: asArray(auth.dkim).filter((d) => d && typeof d === 'object').map((d) => ({
      domain: str(d.domain).toLowerCase(),
      result: str(d.result),
      selector: str(d.selector),
    })),
    spf: asArray(auth.spf).filter((s) => s && typeof s === 'object').map((s) => ({
      domain: str(s.domain).toLowerCase(),
      result: str(s.result),
      scope: str(s.scope),
    })),
  };
}

/**
 * DMARC passes when EITHER aligned DKIM or aligned SPF passes (RFC 7489
 * section 6.6.2). The reporter already did the alignment maths in
 * <policy_evaluated>, so trust that over re-deriving alignment from
 * auth_results — receivers apply their own relaxed/strict interpretation and
 * ours would diverge from the verdict that actually decided delivery.
 */
function recordPasses(record) {
  return record.evaluatedDkim === 'pass' || record.evaluatedSpf === 'pass';
}

module.exports = {
  parseXml,
  parseAggregateReport,
  unpackReport,
  unzipSingleEntry,
  recordPasses,
  asArray,
  decodeEntities,
};
